package com.orderflow.delivery.service;import com.orderflow.delivery.domain.*;import com.orderflow.delivery.dto.*;import org.springframework.stereotype.Component;
@Component public class DeliveryMapper{public DeliveryResponse response(Delivery d){var a=d.address();return new DeliveryResponse(d.getId(),d.getOrderId(),d.getStatus(),d.getDeliveryAgentId(),new DeliveryAddressResponse(a.recipientName(),a.city(),a.stateOrRegion(),a.countryCode()),d.getAssignedAt(),d.getPickedUpAt(),d.getOutForDeliveryAt(),d.getDeliveredAt(),d.getFailedAt(),d.getCancelledAt(),d.getVersion());}public HistoryResponse history(DeliveryStatusHistory h){return new HistoryResponse(h.getPreviousStatus(),h.getNewStatus(),h.getActorUserId(),h.getSourceEventId(),h.getCorrelationId(),h.getChangedAt());}}
